// MeasurementHarnessTests.swift
// Independent-measurement tests for the EQ engine.
//
// Until now the suite verified the filter maths only against itself. These
// tests pin the engine against references computed outside this codebase:
//  1. RBJ Audio EQ Cookbook golden vectors, generated by an independent
//     implementation of the published formulae (Python/NumPy, 2026-11-12).
//  2. The continuous-time (analogue) prototype response: the decramped
//     designer must track it at high frequencies where the RBJ design
//     measurably does not ("cramping").
//  3. Left/right design symmetry through the stager (regression: the right
//     channel was once designed by a different designer on preset loads).
//  4. Auto-preamp behaviour end to end through the stager.
//  5. The true-peak limiter ceiling.

import XCTest
@testable import equmaczer

final class MeasurementHarnessTests: XCTestCase {

    private let sampleRate = 48000.0

    // MARK: - 1. RBJ Golden Vectors

    /// Coefficients (b0, b1, b2, a1, a2) computed independently from the
    /// Audio EQ Cookbook formulae; fs = 48 kHz throughout.
    private struct GoldenCase {
        let type: FilterType
        let frequency: Double
        let q: Double
        let gain: Double
        let expected: [Double]
    }

    func testRBJGoldenVectors() {
        let cases: [GoldenCase] = [
            GoldenCase(type: .parametric, frequency: 1000, q: 1.0, gain: 6.0,
                       expected: [1.04395308699, -1.89532072394, 0.86772228476, -1.89532072394, 0.91167537175]),
            GoldenCase(type: .parametric, frequency: 12000, q: 2.0, gain: -6.0,
                       expected: [0.869822286787, 0.0, 0.608227506687, 0.0, 0.478049793474]),
            GoldenCase(type: .lowPass, frequency: 5000, q: 0.7071, gain: 0.0,
                       expected: [0.0722306668752, 0.14446133375, 0.0722306668752, -1.1092255915, 0.398148259004]),
            GoldenCase(type: .highPass, frequency: 120, q: 0.7071, gain: 0.0,
                       expected: [0.988954143886, -1.97790828777, 0.988954143886, -1.97778627543, 0.978030300116]),
            GoldenCase(type: .lowShelf, frequency: 200, q: 1.0, gain: 7.5,
                       expected: [1.00578663548, -1.97838200112, 0.973639801193, -1.97868400149, 0.979124436304]),
            GoldenCase(type: .highShelf, frequency: 8000, q: 1.0, gain: -4.0,
                       expected: [0.733117941056, -0.411592226901, 0.273697393749, -0.82640069039, 0.421623798294]),
            GoldenCase(type: .notch, frequency: 3000, q: 4.0, gain: 0.0,
                       expected: [0.954348337802, -1.76340579236, 0.954348337802, -1.76340579236, 0.908696675604]),
            GoldenCase(type: .bandPass, frequency: 2500, q: 1.5, gain: 0.0,
                       expected: [0.0967771560075, 0.0, -0.0967771560075, -1.71057784925, 0.806445687985]),
        ]

        for c in cases {
            let coeffs = BiquadMath.calculateCoefficients(
                type: c.type,
                sampleRate: sampleRate,
                frequency: c.frequency,
                q: c.q,
                gain: c.gain
            )
            let actual = [coeffs.b0, coeffs.b1, coeffs.b2, coeffs.a1, coeffs.a2]
            for i in 0..<5 {
                XCTAssertEqual(
                    actual[i], c.expected[i], accuracy: 1e-9,
                    "\(c.type) f0=\(c.frequency) coefficient \(i): got \(actual[i]), golden \(c.expected[i])"
                )
            }
        }
    }

    // MARK: - 2. Decramped Designer vs Analogue Prototype

    func testDecrampedPeakingTracksAnalogueWhereRBJCramps() {
        let f0 = 16000.0
        let q = 1.5
        let gain = 8.0

        let svf = SVFMath.calculateDecrampedSVF(
            type: .parametric, sampleRate: sampleRate, frequency: f0, q: q, gain: gain
        )
        let rbj = BiquadMath.calculateCoefficients(
            type: .parametric, sampleRate: sampleRate, frequency: f0, q: q, gain: gain
        )

        // Exact peak at the centre frequency.
        let digitalAtF0 = SVFMath.digitalMagnitudeDB(svf, sampleRate: sampleRate, at: f0)
        XCTAssertEqual(digitalAtF0, gain, accuracy: 0.1, "decramped peak at f0")

        // The decramped curve tracks the analogue prototype up the top octave;
        // the RBJ curve falls several dB short (independently measured error
        // at 20 kHz: 4.24 dB).
        for f in [18000.0, 19000.0, 20000.0] {
            let analogue = SVFMath.analogMagnitudeDB(
                type: .parametric, frequency: f0, q: q, gain: gain, at: f
            )
            let decramped = SVFMath.digitalMagnitudeDB(svf, sampleRate: sampleRate, at: f)
            XCTAssertEqual(
                decramped, analogue, accuracy: 0.5,
                "decramped response at \(f) Hz should track the analogue prototype"
            )
        }

        let analogueAt20k = SVFMath.analogMagnitudeDB(
            type: .parametric, frequency: f0, q: q, gain: gain, at: 20000.0
        )
        let rbjAt20k = SVFMath.digitalMagnitudeDB(rbj, sampleRate: sampleRate, at: 20000.0)
        XCTAssertGreaterThan(
            analogueAt20k - rbjAt20k, 3.0,
            "RBJ cramping error at 20 kHz should exceed 3 dB (measured 4.24 dB)"
        )
    }

    // MARK: - 5. True-Peak Limiter Ceiling

    func testTruePeakLimiterHonoursCeiling() {
        let ceilingDBTP: Float = -1.0
        let ceilingLinear = pow(10.0, Double(ceilingDBTP) / 20.0)
        let limiter = TruePeakLimiter(ceilingDBTP: ceilingDBTP)

        // Over-ceiling sine burst (1.2 amplitude = +1.58 dBFS).
        let count = 9600
        var buffer = [Float](repeating: 0, count: count)
        for i in 0..<count {
            buffer[i] = Float(1.2 * sin(2.0 * Double.pi * 2000.0 * Double(i) / sampleRate))
        }
        let inputPeak = buffer.map { abs($0) }.max() ?? 0
        XCTAssertGreaterThan(Double(inputPeak), ceilingLinear)

        buffer.withUnsafeMutableBufferPointer { ptr in
            limiter.processInPlace(buffer: ptr.baseAddress!, frameCount: count)
        }

        let outputPeak = buffer.map { abs($0) }.max() ?? 0
        XCTAssertLessThanOrEqual(
            Double(outputPeak), ceilingLinear + 0.01,
            "limiter output peak \(outputPeak) exceeds ceiling \(ceilingLinear)"
        )
    }
}

// MARK: - 3 & 4. Stager-Level Tests (MainActor)

@MainActor
final class StagerMeasurementTests: XCTestCase {

    private let sampleRate = 48000.0

    /// Regression test for the left/right designer asymmetry: with identical
    /// band settings, the stager must design both channels identically, with
    /// the decramped designer — never the legacy RBJ designer.
    func testStagerDesignsBothChannelsIdenticallyWithDecrampedDesigner() {
        let config = EQConfiguration(initialBandCount: 10)
        config.setChannelMode(.stereo)

        // Band 9: 16 kHz, +8 dB, Q 1.5 on both channels — the region where
        // the two designers disagree by several dB.
        config.updateBandFrequency(index: 9, frequency: 16000, channel: .both)
        config.updateBandQ(index: 9, q: 1.5, channel: .both)
        config.updateBandGain(index: 9, gain: 8, channel: .both)

        let stager = EQCoefficientStager(eqConfiguration: config)
        stager.setCurrentSampleRate(sampleRate)

        let left = stager.designedCoefficients(
            for: config.leftState.userEQ.bands, count: config.activeBandCount
        )
        let right = stager.designedCoefficients(
            for: config.rightState.userEQ.bands, count: config.activeBandCount
        )
        XCTAssertEqual(left, right, "identical settings must design identical channels")

        let expected = SVFMath.calculateDecrampedSVF(
            type: .parametric, sampleRate: sampleRate, frequency: 16000, q: 1.5, gain: 8
        )
        XCTAssertEqual(left[9], expected, "band 9 must come from the decramped designer")

        // And it must audibly differ from what the legacy designer produced.
        let rbj = BiquadMath.calculateCoefficients(
            type: .parametric, sampleRate: sampleRate, frequency: 16000, q: 1.5, gain: 8
        )
        let decrampedAt20k = SVFMath.digitalMagnitudeDB(left[9], sampleRate: sampleRate, at: 20000)
        let rbjAt20k = SVFMath.digitalMagnitudeDB(rbj, sampleRate: sampleRate, at: 20000)
        XCTAssertGreaterThan(decrampedAt20k - rbjAt20k, 1.0)
    }

    /// Auto-preamp: stacked boosts must pull the effective input gain down by
    /// the composite peak (plus the 0.2 dB inter-sample margin); flat bands
    /// must leave it at zero; disabling the toggle must remove it.
    func testAutoPreampReactsToStackedBoosts() {
        let config = EQConfiguration(initialBandCount: 10)
        let stager = EQCoefficientStager(eqConfiguration: config)
        stager.setCurrentSampleRate(sampleRate)

        // Two well-separated +12 dB peaks. (Band slots are a 64-band log
        // spread, so frequencies are set explicitly — neighbouring slots
        // would stack into a single ~21 dB composite peak.)
        config.updateBandFrequency(index: 5, frequency: 1000)
        config.updateBandFrequency(index: 7, frequency: 4000)
        config.updateBandGain(index: 5, gain: 12)
        config.updateBandGain(index: 7, gain: 12)
        stager.reapplyConfiguration()

        XCTAssertLessThanOrEqual(config.autoPreampDB, -12.0,
                                 "stacked +12 dB boosts need at least 12 dB of preamp")
        XCTAssertGreaterThanOrEqual(config.autoPreampDB, -16.0,
                                    "preamp should track the composite peak, not over-cut")
        XCTAssertEqual(
            config.effectiveInputGainDB,
            config.inputGain + config.autoPreampDB,
            accuracy: 0.001
        )

        // Flatten: preamp returns to zero.
        config.updateBandGain(index: 5, gain: 0)
        config.updateBandGain(index: 7, gain: 0)
        stager.reapplyConfiguration()
        XCTAssertEqual(config.autoPreampDB, 0, accuracy: 0.001)

        // Toggle off: effective gain ignores the preamp.
        config.updateBandGain(index: 5, gain: 12)
        stager.reapplyConfiguration()
        XCTAssertLessThan(config.autoPreampDB, -12.0 + 0.5)
        config.autoPreampEnabled = false
        XCTAssertEqual(config.effectiveInputGainDB, config.inputGain, accuracy: 0.001)
    }
}
